// src/components/editor/RichTextInput.tsx
"use client";

import React, {useEffect} from "react";
import {useEditor, EditorContent} from "@tiptap/react";
import StarterKit from "@tiptap/starter-kit";
import Underline from "@tiptap/extension-underline";
import Link from "@tiptap/extension-link";
import {
  Bold,
  Italic,
  Underline as UnderlineIcon,
  Link as LinkIcon,
} from "lucide-react";

interface RichTextInputProps {
  value: string;
  onChange: (html: string) => void;
  placeholder?: string;
  multiline?: boolean;
}

/**
 * Strips outer <p>...</p> wrapper generated by Tiptap so inline bullets
 * and summaries render cleanly inside <li> and <div> tags.
 */
function stripOuterParagraphs(html: string): string {
  return html
    .replace(/^<p>/i, "")
    .replace(/<\/p>$/i, "")
    .replace(/<\/p><p>/gi, "<br />")
    .trim();
}

export function RichTextInput({
  value,
  onChange,
  placeholder = "Write achievement or summary...",
  multiline = false,
}: RichTextInputProps) {
  const editor = useEditor({
    immediatelyRender: false,
    extensions: [
      StarterKit.configure({
        heading: false,
        bulletList: false,
        orderedList: false,
        listItem: false,
        blockquote: false,
        codeBlock: false,
        horizontalRule: false,
      }),
      Underline,
      Link.configure({
        openOnClick: false,
        HTMLAttributes: {
          target: "_blank",
          rel: "noopener noreferrer",
        },
      }),
    ],
    content: value || "",
    editorProps: {
      attributes: {
        class: `w-full px-2.5 py-1.5 text-xs text-zinc-100 focus:outline-none ${
          multiline ? "min-h-[72px]" : "min-h-[34px]"
        }`,
      },
    },
    onUpdate: ({editor: ed}) => {
      const rawHtml = ed.getHTML();
      const cleaned = ed.isEmpty ? "" : stripOuterParagraphs(rawHtml);
      onChange(cleaned);
    },
  });

  // Keep editor in sync if Undo/Redo or Sample Reset changes the value externally
  useEffect(() => {
    if (!editor) return;
    const currentCleaned = editor.isEmpty
      ? ""
      : stripOuterParagraphs(editor.getHTML());
    if (value !== currentCleaned && !editor.isFocused) {
      editor.commands.setContent(value || "", {emitUpdate: false});
    }
  }, [value, editor]);

  if (!editor) {
    return (
      <div className="h-9 w-full animate-pulse rounded-md border border-zinc-800 bg-zinc-950" />
    );
  }

  const handleSetLink = () => {
    const previousUrl = editor.getAttributes("link").href as string | undefined;
    const url = window.prompt(
      "Enter URL (e.g. https://github.com/...)",
      previousUrl || "https://",
    );
    if (url === null) return;
    if (url.trim() === "") {
      editor.chain().focus().extendMarkRange("link").unsetLink().run();
      return;
    }
    editor
      .chain()
      .focus()
      .extendMarkRange("link")
      .setLink({href: url.trim()})
      .run();
  };

  return (
    <div className="flex-1 rounded-md border border-zinc-800 bg-zinc-950 focus-within:border-blue-500 transition-colors">
      {/* Mini Inline Formatting Toolbar */}
      <div className="flex items-center justify-between border-b border-zinc-800/80 bg-zinc-900/60 px-1.5 py-0.5">
        <div className="flex items-center gap-0.5">
          <button
            type="button"
            onClick={() => editor.chain().focus().toggleBold().run()}
            title="Bold (Ctrl+B)"
            className={`rounded p-1 transition ${
              editor.isActive("bold")
                ? "bg-blue-600/30 text-blue-300"
                : "text-zinc-400 hover:bg-zinc-800 hover:text-zinc-200"
            }`}>
            <Bold className="h-3 w-3" />
          </button>

          <button
            type="button"
            onClick={() => editor.chain().focus().toggleItalic().run()}
            title="Italic (Ctrl+I)"
            className={`rounded p-1 transition ${
              editor.isActive("italic")
                ? "bg-blue-600/30 text-blue-300"
                : "text-zinc-400 hover:bg-zinc-800 hover:text-zinc-200"
            }`}>
            <Italic className="h-3 w-3" />
          </button>

          <button
            type="button"
            onClick={() => editor.chain().focus().toggleUnderline().run()}
            title="Underline (Ctrl+U)"
            className={`rounded p-1 transition ${
              editor.isActive("underline")
                ? "bg-blue-600/30 text-blue-300"
                : "text-zinc-400 hover:bg-zinc-800 hover:text-zinc-200"
            }`}>
            <UnderlineIcon className="h-3 w-3" />
          </button>

          <button
            type="button"
            onClick={handleSetLink}
            title="Insert/Edit Link"
            className={`rounded p-1 transition ${
              editor.isActive("link")
                ? "bg-blue-600/30 text-blue-300"
                : "text-zinc-400 hover:bg-zinc-800 hover:text-zinc-200"
            }`}>
            <LinkIcon className="h-3 w-3" />
          </button>
        </div>

        {editor.isEmpty && (
          <span className="pr-1 text-[10px] text-zinc-500 truncate max-w-[180px]">
            {placeholder}
          </span>
        )}
      </div>

      {/* Editable Content Area */}
      <EditorContent editor={editor} />
    </div>
  );
}
